"use strict";
let PAIRS=[],position=0,labels={};const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const key=()=>`hk-record-review-v1-${$('#slot').value}`;
function load(){try{labels=JSON.parse(localStorage.getItem(key())||'{}')}catch{labels={}}position=0;render()}
function store(){localStorage.setItem(key(),JSON.stringify(labels))}
function current(){return labels[PAIRS[position].pair_id]||{decision:'',evidence_and_reason:'',reviewer_name:'',reviewed_at:''}}
function render(){const p=PAIRS[position],v=current();if(!p)return;$('#progress').textContent=`Pair ${position+1} of ${PAIRS.length}. ${Object.values(labels).filter(x=>x.decision&&x.evidence_and_reason&&x.reviewer_name).length} complete with a name and reason.`;$('#review-card').innerHTML=`<p class="eyebrow">${esc(p.pair_id)} · ${esc(p.district)}</p><div class="table-wrap"><table><thead><tr><th>Evidence</th><th>FEHD branch</th><th>${esc(p.candidate_source)} candidate</th></tr></thead><tbody><tr><th>Names</th><td>${esc(p.fehd_name_en)}<br>${esc(p.fehd_name_zh)}</td><td>${esc(p.candidate_names)}</td></tr><tr><th>Address</th><td>${esc(p.fehd_address_en)}<br>${esc(p.fehd_address_zh)}</td><td>${esc(p.candidate_addresses||'Not supplied')}</td></tr><tr><th>Coordinates</th><td>${esc(JSON.stringify(p.fehd_coords))}</td><td>${esc(JSON.stringify(p.candidate_coords))}</td></tr><tr><th>IDs</th><td>${esc(p.fehd_licence_ids)}</td><td>${esc(p.candidate_id)}</td></tr></tbody></table></div>${p.candidate_source==='OSM'?`<p><a href="${esc(p.candidate_url)}" target="_blank" rel="noreferrer">Inspect the original OSM record</a></p>`:''}<div class="review-actions">${['Match','Non-match','Uncertain'].map(d=>`<button class="secondary" data-decision="${d}" aria-pressed="${v.decision===d}">${d}</button>`).join('')}</div><label>Evidence and reason<textarea id="reason" rows="3" placeholder="Explain the branch-level evidence and any conflicting details">${esc(v.evidence_and_reason)}</textarea></label><div class="review-actions"><button class="secondary" id="previous" ${position===0?'disabled':''}>Previous</button><button class="primary" id="save">Save decision</button><button class="secondary" id="next" ${position===PAIRS.length-1?'disabled':''}>Next</button></div><p id="message" class="small-note" aria-live="polite"></p>`;$('#review-card').querySelectorAll('[data-decision]').forEach(b=>b.onclick=()=>{$('#review-card').querySelectorAll('[data-decision]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});$('#previous').onclick=()=>{position--;render()};$('#next').onclick=()=>{position++;render()};$('#save').onclick=()=>{const decision=$('[data-decision][aria-pressed="true"]')?.dataset.decision,name=$('#reviewer-name').value.trim(),reason=$('#reason').value.trim();if(!decision||!name||!reason){$('#message').textContent='Choose a decision and enter your name and evidence before saving.';return}labels[p.pair_id]={decision,reviewer_name:name,evidence_and_reason:reason,reviewed_at:new Date().toISOString()};store();render();$('#message').textContent='Saved in this browser. Export your CSV when finished.'}}
function exportCSV(){const fields=['pair_id','reviewer_name','decision','evidence_and_reason','reviewed_at'];const q=v=>'"'+String(v??'').replaceAll('"','""')+'"';const text='\ufeff'+[fields,...PAIRS.map(p=>[p.pair_id,...fields.slice(1).map(k=>(labels[p.pair_id]||{})[k]||'')])].map(row=>row.map(q).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));a.download=`reviewer_${$('#slot').value}_decisions.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
fetch('review_pairs.json').then(r=>{if(!r.ok)throw Error('Review file unavailable');return r.json()}).then(d=>{PAIRS=d;$('#slot').onchange=load;$('#export').onclick=exportCSV;load()}).catch(e=>{$('#review-card').textContent=e.message});
